window.POETRY_REGISTER("v5-extra-10-9-0-3d3e33db83ee.js",{"poems":[[22854,2],[25872,2],[51948,2],[51955,2],[51967,2],[52008,2],[52172,2],[52539,2],[52740,2],[54092,2],[54370,2],[54508,2],[57321,2],[57628,2],[58026,2],[94417,7],[96418,7],[116347,7],[116512,7],[116979,7],[125885,7],[136230,7],[136921,7],[140225,7],[141934,7],[145726,7],[169925,7],[178023,7],[199110,7],[230810,7],[233355,7],[238528,7],[251336,7],[256834,7],[271951,7],[271989,7],[274568,7],[280396,7],[286733,7],[288138,7],[291948,7],[295324,7],[306947,7],[309525,7],[317146,7],[346975,9],[350997,9],[351009,9],[359688,9],[359710,9],[360387,9],[365412,9],[366623,9],[368387,10],[370712,10],[373001,10],[374457,10],[375294,10],[375309,10],[380143,10],[381853,0],[381867,0],[390992,13],[401961,8],[413917,8],[415377,8],[422390,8],[425776,8],[426223,8],[431910,8],[431924,8],[435043,8],[436482,8],[442436,8],[442494,8],[488526,8],[488527,8],[514232,8],[523991,8],[524929,8],[540569,8],[562845,8],[566085,8],[573984,8],[575776,8],[596197,8],[597889,8],[630355,8],[635999,15],[636034,15],[636035,15],[637916,15],[646993,15],[648431,16],[648482,16],[648567,16],[650074,5],[650387,5],[650841,5],[671605,5],[671724,5],[684303,5],[709993,5],[730125,5],[733047,5],[735220,5]],"pairs":[["犹驱饿民运造化防暑阨","吾闻躬耕南亩舜之圣",0],["的不能匡君辅国活生民","下无巢父许由箕颍操",1],["郑珣瑜郑余庆为其从昆","知应为贞元元和间人",2],["因滤水罗正不必密致也","密慎与下文疎通对文",3],["给我提出了很好的意见","并校出一些错误的字",4],["马的年龄显然超过怀素","敦煌陷蕃在建中二年",5],["伯三七一六卷作金百倾","伯三六五六作百金倾",6],["大和初任福建团练副使","会昌五年为夔州刺史",7],["刑部侍郎潘娇奏其妖怪","帝命武士于相市戮之",8],["因知此诗应为魏玄同作","作韦玄同为音近而误",9],["仙人张绰传为咸通初人","与本诗作者时代不合",10],["谓世传唐玄宗有诗云云","明皇平行迹未及东南",11],["知王仲举为何仲举之误","二书所载及第年有异",12],["此诗风格不类僧鸾之作","僧鸾又未见入蜀之迹",13],["不知是薛调同时人所作","还是宋代人所附加的",14],["欲及八月十五夜观洪涛","洗荡生前邑邑不平气",15],["宠荣声利不可以苟屈兮","自非青云白石有深趣",16],["我欲往兮方穷处于蓬蒿","恩之大兮报不可以速",17],["不忠于所事兮其将何求","蛾眉皓齿兮乃妾之雠",18],["彼为辕下驹兮我方鹰扬","彼作威之臣人莫敢当",19],["颀然而长者黄冠而羽衣","澣颐坦腹盘石箕坐兮",20],["写溪声兮延五老以为寿","蝉蜕尘埃兮玉雪自清",21],["无事兮我以观万物之情","儿时所蓺兮桃李纤纤",22],["敬谢有功兮宜奠于泉下","吾之将归兮星律回秋",23],["颀然而长者黄冠兮羽衣","轩颐坦腹涛石箕坐兮",24],["每人痛与一顿何为如此","且教伊不敢掣风掣颠",25],["浮我江䑳兮岁不知其几","石中之人兮喜我不屑",26],["转自己归山河大地则难","有人道得不难不易句",27],["如悬崖万仞龙盘古树枝","又如生马不施鞚而驰",28],["非金玉之人兮孰振吾过","有牵其复兮有倡其和",29],["从教激风怒窍拔木折石","一去旬有五日而后返",30],["几弭节兮念遗民而来顾","高弁苍苍兮清苕弥弥",31],["甚不爱湛溪千顷涨葡萄","蟠桃入口那能甘比蜜",32],["去来有节兮春秋兮其旅","良时赓歌兮对尔吟哦",33],["则片言只字之落人间者","世固待之以褚颜之节",34],["殆有类乎鱼鸢之在天渊","各自得以遂其高深也",35],["美师之德兮色重里胶青","妙高万叠兮春归锦镜",36],["昨之折槛今复饰以成杠","背苏堤万丝之绿阴兮",37],["都且闲兮神乎何以为御","振策而风兮回轩为雨",38],["渡梅花之桥兮龙㡛镳镳","有美君子兮苍梧翠竹",39],["亦不吟依本胡芦取天怒","但愿冰棱雪块在心胸",40],["五十年闺闼兮甯识马嘶","衔辔迫人兮魂为之飞",41],["有时驾铁船于须弥顶上","有时倒骑骏马骤高楼",42],["歌曰鹤怨猿惊兮在空谷","四十余年萍蓬将七十",43],["自古孰无死兮首丘为正","我行我行兮梦寐所思",44],["应令猺子感眼眦迸垂浆","将军我三十年之弟兄",45],["只今圣王敷五教举逸民","一朝征车轰动龙伯国",46],["安知便以神为马尻为轮","飞度蓬莱弱水三万里",47],["居沂之人兮宽裕而善良","古之人古之人兮翱翔",48],["山中之人兮和乐而有仪","余心休休兮媚余匪他",49],["君不见干将莫邪困丰城","化为两龙飞去延平津",50],["咨汝魃兮诚忮忍而险愎","凭妖矜孽兮畔戾圣则",51],["又不见杏林种雨年年新","岂如梁君小试医国手",52],["彼以天下让兮我以之逃","世岂无尧兮应尧之求",53],["鹤驾其朝兮窃谢病枕安","须捷萧萧兮云栖檐端",54],["蚁穴封侯之梦何日能醒","亦何异于填海之精卫",55],["又不闻蟠桃一实三千龄","不知此木历年几百万",56],["进无益于世兮退将安归","呜呼巳矣兮吾宁不悲",57],["我维我舟兮聊以搔我首","放歌逍遥兮哀莫予偶",58],["步虚九天上兮不沾世氛","水火交媾兮日月吐吞",59],["三军一飞降兮所向皆殂","一士判死兮而当百夫",60],["雪我王宿耻兮威振八都","军伍难更兮势如貔䝙",60],["呜呼哀哉兮死者不可忘","飞鸟尚然兮况于贞良",61],["歌曰鹤怨猿惊兮在空谷","四十馀年萍蓬将七十",62],["深谋远虑宜一知其所终","无令竹帛专美前人功",63],["但闻惊天伐鼓砰轰喧阗","恨无鲁阳所挥之神戈",64],["思君子兮不得与驾以游","山有出云兮木亦有柯",65],["下渊渊兮惧蛟龙之纠缠","累然踧踖不可以径度",66],["思尧舜与徒兮殊途同行","嗟三百祀兮黄道芜芜",67],["荀琼谢玉亦有时而凋零","予之浩气兮化为风霆",68],["我闻李愿盘谷王维辋川","伊人胸中潇洒自岩壑",69],["不在罗浮之村西湖之屿","乃在淮左竹西最佳处",70],["我不愿千二百岁崆峒居","但愿百年三万六千日",71],["我不愿张苍食乳如鱼呿","愿如昌黎口存十三齿",72],["怀佳人兮路修阻而莫随","涉川无梁兮登山无车",73],["念儿有身兮乃父母之枝","儿思终养兮父不待儿",74],["胡皇舆枉御兮六飞劝勷","孰执其咎兮曰惟巨珰",75],["曰君辱臣死兮惟义之常","死虽可逃兮吾志弗降",75],["归气作厉兮犹剿乎犬羊","缅思是时兮天地苍黄",75],["连蹇孱弱兮惟赢童之是","与幽沉转辗兮遂罹此",76],["痛尔同气兮檗餐而茶茹","怅望闽邦兮逶迟崎峣",76],["酌君以金陵清水之新烧","弦以发君节气之磊落",77],["君不见山空蕙帐猿猱悲","君乎君乎稍且住白厓",78],["却来金陵寻孙楚之酒楼","我闻英绚之姿是孙楚",79],["激流风兮杳不知其所止","松韵高岩兮泉流涧底",80],["老人是百千万劫之馀灰","问其生时朝代不敢说",81],["游不遍天下名山陵与谷","何如瞎驴开眼见主宾",82],["天台之山四万八千丈兮","联冈叠障绵亘乎东南",83],["扫除闲愁与昆明之劫灰","刘郎刘郎绝代颇希有",84],["无乃好事者摸拟希其伦","于乎貌物非物人非人",85],["有约九龙之山太湖之滨","飘乎白日朗诵归来篇",86],["念儿有身兮乃父母之枝","儿思终养兮父不待儿",87],["到如今诸事废此心不灭","尚牵缠想着迎风待月",88],["犹交相蒙蔽而勿置可否","所以纵成凶焰滔天兮",89],["岂徒继东晋南宋之遗芳","胡乃置贤奸于不辨兮",90],["富不愿金谷秦筝按六幺","但愿中秋无云月当午",91],["在于雷欲动而未动之先","为天之命兮所以开干",92],["觉后痛吾心兮无休歇时","十有四拍兮涕泪交垂",93],["于嗟不可悔兮宁早自贼","为王饿死兮谁者怜之",94],["参驾白鹿上至云戏游遨","上建逋阴广里践近高",95],["活吃人的盗跖得了好死","颜渊短命是为的什么",96],["多亏了少康一旅整朝权","四百年又到了商家手",96],["更可笑剪爪当牲来祷告","不成个体统真是歪缠",96],["这才是浆了捞来水里去","一更里荷包照样儿穿",96],["驾前里左排钺斧右金瓜","他生下了儿子一百个",96],["到其间武王纵有千张嘴","谁是谁非也说不分明",96],["落了个扒灰贼头血染沙","沙陀将又做了唐皇帝",96],["又教他长孙行脚历坎坷","三十年的杀运忒苦恼",96],["终有个家亡人散各奔腾","枉费了意悬悬半世心",97],["三百六十界无一青蛾眉","又如先生平生之忧患",98],["我不知击阉之疏草罢时","可曾携汝起舞扬双眉",99],["一望兮万峰起立入胸次","化为突兀磊磈之羁愁",100],["还堪笑去笄填土孰为容","刚得教成歌舞如花艳",101],["软东风暂禁着柳花飞扬","却无端催着桃花飘荡",102],["是啼痕染就了万重熘障","问江南芳草可还惆怅",102],["道里亦如九谷中有粱菰","南人未闻名者徒摩挲",103],["一望兮万峰起立入胸次","化为突兀磊磈之羁愁",104],["终有个家亡人散各奔腾","枉费了意悬悬半世心",105]]});
